TD.add("software-engineering", [

{t:"Version Control", a:"Source Control", d:"A system that records every change to a codebase, so history can be inspected, compared and restored.", l:"core", g:["fundamentals","tooling"],
 b:["Version control answers who changed this line, when, and why; lets several people work on the same codebase without overwriting each other; and makes any past state recoverable. Distributed systems such as git give every clone the full history, so working offline and branching are cheap.",
    "It is also the backbone of everything else in modern engineering practice: code review happens on diffs, CI triggers on commits, deployments are tied to commit hashes, and infrastructure as code and GitOps put configuration under the same discipline."],
 k:["Full history: who changed what, when and why.",
    "Distributed means every clone holds the complete history.",
    "Commit messages are documentation — explain why, not what.",
    "Never commit secrets; history is permanent."],
 dg:"git-branch",
 r:["Git","Branch","Commit","Pull Request","CI/CD"]},

{t:"Git", d:"The distributed version control system used by essentially all modern software development.", l:"core", g:["tool","fundamentals"],
 b:["Git stores snapshots of the whole tree, not diffs, with each commit identified by a hash of its content and its parent. That content-addressing is what makes history tamper-evident and branching almost free — a branch is just a movable pointer to a commit.",
    "Its interface is famously unforgiving because its terminology reflects its internals. Learning the object model — commits, trees, blobs and refs — makes the commands make sense, and most confusion dissolves once you understand that a branch is a pointer and HEAD is where you are."],
 k:["Commits are content-addressed snapshots, not diffs.",
    "A branch is a movable pointer; creating one is nearly free.",
    "The staging area lets you commit part of your working changes.",
    "`git reflog` recovers almost anything you think you have lost."],
 x:{lang:"bash", code:'git switch -c feature/search        # create and switch\ngit add -p                          # stage selected hunks\ngit commit -m "Add cursor pagination to search"\ngit rebase -i main                  # tidy history before review\ngit push -u origin feature/search\n\ngit reflog                          # find a lost commit\ngit restore --source=HEAD~2 file.js # recover one file'},
 dg:"git-branch",
 r:["Version Control","Branch","Merge","Rebase","Pull Request"]},

{t:"Commit", d:"A recorded snapshot of the repository at a point in time, with a message explaining the change.", l:"core", g:["git","fundamentals"],
 b:["A commit stores the full tree state, a pointer to its parent, author and timestamp, and a message. Its identifier is a hash of all of that, so any alteration produces a different hash — which is what makes history verifiable.",
    "Good commits are small and focused on one logical change, which makes review, bisection and reverting all straightforward. The message should explain why the change was made; the diff already shows what changed."],
 k:["A snapshot plus metadata, identified by a content hash.",
    "One logical change per commit — it makes revert and bisect work.",
    "Explain why in the message; the diff shows what.",
    "`git bisect` finds the commit that introduced a bug in log₂ n steps."],
 dg:"git-branch",
 r:["Git","Branch","Version Control","Pull Request"]},

{t:"Branch", d:"A movable pointer to a commit, letting work proceed independently of the main line.", l:"core", g:["git","fundamentals"],
 b:["Because a branch is just a pointer, creating one costs nothing. Work proceeds on the branch and is later merged back. The main line is conventionally `main`, and feature branches are created from it and merged into it.",
    "The important variable is how long branches live. Short-lived branches merged within a day or two rarely conflict; branches living for weeks diverge until merging becomes a project of its own. That divergence is precisely what continuous integration exists to prevent."],
 k:["A branch is a pointer to a commit — creation is instant.",
    "Long-lived branches diverge and make merging painful.",
    "Merge or rebase from main frequently to stay close.",
    "Delete branches after merging; stale branches accumulate confusion."],
 dg:"git-branch",
 r:["Git","Merge","Rebase","Trunk-Based Development","Merge Conflict"]},

{t:"Merge", d:"Combining the changes from one branch into another.", l:"core", g:["git","fundamentals"],
 b:["Git finds the common ancestor of the two branches and combines the changes each made since. When the same lines changed on both sides it cannot decide, and reports a conflict for a human to resolve.",
    "A merge commit has two parents and preserves the true history of when work happened in parallel. A fast-forward merge simply moves the pointer when there is nothing to combine. Squash merging condenses a branch into a single commit, which keeps main history linear at the cost of losing the intermediate steps."],
 k:["Three-way merge using the common ancestor of both branches.",
    "Conflicts occur when the same lines changed on both sides.",
    "Merge commits preserve parallel history; squash merges flatten it.",
    "Merging main into your branch often keeps conflicts small."],
 dg:"git-branch",
 r:["Branch","Rebase","Merge Conflict","Git"]},

{t:"Rebase", d:"Replaying a branch's commits on top of another branch, producing a linear history.", l:"intermediate", g:["git","fundamentals"],
 b:["Rather than creating a merge commit, rebase takes your commits and reapplies them onto the latest main, as though you had started from there. The result is a straight line of history that is easier to read and to bisect.",
    "The rule that matters: never rebase commits that others have pulled. Rebasing rewrites commit hashes, so anyone who already has the old commits ends up with a divergent history. Interactive rebase before opening a pull request is the safe and useful case."],
 k:["Rewrites history — commit hashes change.",
    "Never rebase a branch others have already pulled.",
    "Interactive rebase tidies your own commits before review.",
    "Produces linear history that is easier to read and bisect."],
 r:["Merge","Branch","Git","Merge Conflict"]},

{t:"Merge Conflict", d:"A state where git cannot automatically combine two sets of changes to the same lines.", l:"core", g:["git","fundamentals"],
 b:["When both branches modified the same region, git marks the conflict with `<<<<<<<`, `=======` and `>>>>>>>` and asks you to produce the correct result. That decision requires understanding both changes — it is not mechanical.",
    "Conflicts scale with divergence, so the real remedy is prevention: merge from main frequently, keep branches short-lived and changes small, and coordinate before large refactors that touch many files. `git rerere` remembers how you resolved a conflict and reapplies it."],
 k:["Only occurs when the same lines changed on both sides.",
    "Resolution requires understanding both changes, not picking one.",
    "Frequency scales with how long branches live.",
    "Always run the tests after resolving — a clean merge can still be wrong."],
 r:["Merge","Rebase","Branch","Trunk-Based Development"]},

{t:"Pull Request", a:"Merge Request", d:"A proposal to merge a branch, providing a place for review and automated checks before it lands.", l:"core", g:["practice","collaboration"],
 b:["A pull request shows the diff, runs CI, and gives reviewers somewhere to comment. It is the standard quality gate in modern development: nothing reaches main without passing checks and getting at least one approval.",
    "Size dominates review quality. A 100-line pull request gets meaningful scrutiny; a 2,000-line one gets looks fine to me. Keeping them small, describing what changed and why, and explaining how to verify it are what make review actually work."],
 k:["Small pull requests get real review; large ones get rubber-stamped.",
    "Describe what changed, why, and how to verify.",
    "Automated checks should catch style and correctness before a human looks.",
    "Draft pull requests invite early feedback on direction."],
 r:["Code Review","Git","CI/CD","Branch","Trunk-Based Development"]},

{t:"Code Review", d:"Having another engineer read a change before it is merged.", l:"core", g:["practice","quality"],
 b:["Review catches bugs, spreads knowledge of the codebase, maintains consistency and gives newer engineers a feedback loop. Studies consistently find it among the most cost-effective defect-detection practices available.",
    "What makes it work is focus and tone. Reviewers should concentrate on correctness, design and clarity, and leave formatting to automated tools. Comments should be specific and about the code, and reviewers should distinguish blocking concerns from preferences — otherwise review becomes a source of friction rather than quality."],
 k:["Catches defects, spreads knowledge and maintains consistency.",
    "Automate formatting so review can focus on substance.",
    "Distinguish blocking issues from optional suggestions explicitly.",
    "Review promptly — a pull request waiting two days blocks someone."],
 r:["Pull Request","Static Analysis","Pair Programming","Linter"]},

{t:"Trunk-Based Development", d:"Everyone integrates small changes into one main branch at least daily, using flags to hide unfinished work.", l:"intermediate", g:["practice","workflow"],
 b:["Rather than long-lived feature branches, changes go to main quickly — either directly or via short-lived branches merged within a day. Incomplete features hide behind feature flags rather than in unmerged branches.",
    "This is what continuous integration originally meant, and the DORA research consistently associates it with higher delivery performance. It requires solid automated tests and feature flags; without those, merging incomplete work to main is reckless rather than agile."],
 k:["Branches live hours or days, not weeks.",
    "Feature flags hide incomplete work instead of unmerged branches.",
    "Requires strong automated testing to be safe.",
    "Consistently associated with higher delivery performance in DORA research."],
 r:["Continuous Integration","Feature Flag","Branch","CI/CD","Pull Request"]},

{t:"Monorepo", d:"Keeping many projects or services in a single repository.", l:"intermediate", g:["practice","tooling"],
 b:["A monorepo makes cross-project changes atomic — updating a shared library and every consumer happens in one commit — and gives everyone one version of every internal dependency, eliminating diamond dependency problems. Google, Meta and Microsoft all use them at enormous scale.",
    "The costs are tooling. Naive CI rebuilds everything on every change, so you need build systems that understand the dependency graph and rebuild only what is affected — Bazel, Nx, Turborepo. Access control also becomes coarser."],
 k:["Atomic cross-project changes; one version of every internal dependency.",
    "Requires a build system that understands affected-project graphs.",
    "Naive CI rebuilding everything is the classic failure.",
    "Polyrepo gives independence at the cost of coordination."],
 r:["Version Control","Build Tool","CI/CD","Git"]},

{t:"Semantic Versioning", a:"SemVer", d:"A version numbering scheme where MAJOR.MINOR.PATCH communicates the nature of each change.", l:"core", g:["practice","standard"],
 b:["Increment MAJOR for breaking changes, MINOR for backward-compatible additions, PATCH for backward-compatible fixes. Consumers can then decide their update policy: accept patches automatically, review minors, plan for majors.",
    "It only works if maintainers apply it honestly, and the definition of breaking is subtler than it appears — a bug fix that someone depended on is a breaking change in practice. Version 0.x explicitly signals that anything may change."],
 k:["MAJOR breaks, MINOR adds compatibly, PATCH fixes compatibly.",
    "`^1.2.3` accepts minors and patches; `~1.2.3` accepts patches only.",
    "0.x means no stability guarantees at all.",
    "Fixing behaviour someone relied on is a breaking change in practice."],
 r:["API Versioning","Package Manager","npm","Changelog"]},

{t:"Changelog", d:"A curated, human-readable record of notable changes in each release.", l:"core", g:["practice","documentation"],
 b:["A changelog is not a commit log. It is written for the people who use the software, grouping changes as added, changed, deprecated, removed, fixed and security, with breaking changes and migration steps called out clearly.",
    "Conventional commit messages allow much of it to be generated automatically, but the migration guidance for breaking changes still has to be written by a human who understands the impact."],
 k:["Written for users, not derived mechanically from commits.",
    "Group by type; call out breaking changes prominently.",
    "Include migration steps for anything that breaks.",
    "Conventional commits enable partial automation."],
 r:["Semantic Versioning","Documentation","Version Control"]},

{t:"Unit Test", d:"An automated test of a single unit of code in isolation from its dependencies.", l:"core", g:["testing","practice"],
 b:["Unit tests run in milliseconds, need no database or network, and pinpoint failures precisely because they exercise one thing. They form the base of the test pyramid — the most numerous and the fastest layer.",
    "The recurring debate is how much to isolate. Mocking every dependency produces tests that verify implementation rather than behaviour, and that break on every refactor. Testing a unit with its real collaborators, mocking only genuinely external systems, generally produces more durable tests."],
 k:["Fast, isolated, deterministic — no network, no database, no clock.",
    "Test behaviour, not implementation, or refactoring breaks every test.",
    "Over-mocking produces tests that pass while the system is broken.",
    "The base of the pyramid: most numerous, fastest, cheapest."],
 dg:"test-pyramid",
 r:["Integration Test","Test Pyramid","Mocking","Test-Driven Development","Test Coverage"]},

{t:"Integration Test", d:"A test that verifies several components work correctly together.", l:"core", g:["testing","practice"],
 b:["Integration tests exercise the wiring: does the repository actually write to the database, does the API handler return the right shape, does the message consumer commit its offset. They catch the mismatches that unit tests with mocks structurally cannot.",
    "Testcontainers made these substantially more practical by spinning up a real database or message broker in Docker for the test run, so you test against the actual technology rather than an in-memory substitute that behaves differently."],
 k:["Verifies the seams between components — where mocked unit tests are blind.",
    "Testcontainers runs the real database in Docker for the test.",
    "Slower than unit tests; fewer of them in the pyramid.",
    "In-memory database substitutes hide real behaviour differences."],
 dg:"test-pyramid",
 r:["Unit Test","End-to-End Test","Test Pyramid","Docker"]},

{t:"End-to-End Test", a:"E2E Test", d:"A test that drives the whole system as a user would, through its real interface.", l:"core", g:["testing","practice"],
 b:["End-to-end tests click through the actual application against real services, verifying that complete user journeys work. They catch integration failures nothing else does, and they are the only tests that verify the thing users actually experience.",
    "They are also slow, expensive to maintain and prone to flakiness from timing and environment variability. Keep them few and focused on critical paths — checkout, login, the core workflow — and let faster layers cover everything else."],
 k:["Highest confidence, highest cost, slowest to run.",
    "Keep to critical user journeys only.",
    "Flakiness usually comes from timing — wait for conditions, never for durations.",
    "Playwright and Cypress are the current standard tools."],
 dg:"test-pyramid",
 r:["Integration Test","Test Pyramid","Flaky Test"]},

{t:"Test Pyramid", d:"A guideline for test suite composition: many fast unit tests, fewer integration tests, very few end-to-end tests.", l:"core", g:["testing","practice"],
 b:["The shape follows from cost and speed. Unit tests are cheap, fast and precise, so have thousands. Integration tests are slower and broader, so have hundreds. End-to-end tests are slow, brittle and expensive, so have a handful covering critical journeys.",
    "Inverting the pyramid — the ice cream cone — produces a suite that takes an hour, fails randomly, and that nobody trusts. The pyramid is a heuristic rather than a law; the underlying principle is to test at the lowest level that gives real confidence."],
 k:["Many unit, fewer integration, very few end-to-end.",
    "An inverted pyramid produces a slow, flaky, distrusted suite.",
    "Test at the lowest level that gives genuine confidence.",
    "Suite runtime determines whether people actually run it."],
 dg:"test-pyramid",
 r:["Unit Test","Integration Test","End-to-End Test","Test Coverage"]},

{t:"Test-Driven Development", a:"TDD", d:"Writing a failing test first, then the minimum code to pass it, then refactoring.", l:"core", g:["testing","practice"],
 b:["The red-green-refactor cycle forces you to define expected behaviour before implementing it, which tends to produce simpler designs and better interfaces — you experience the API as a caller before you build it. It also guarantees every line of code has a test that fails without it.",
    "It is not universally applicable: exploratory work, spikes and UI experimentation often go faster without it. Treat it as a technique that fits some problems well rather than as an identity."],
 k:["Red, green, refactor — and the refactor step is not optional.",
    "Designing the API from the caller's perspective is the main benefit.",
    "Guarantees each line is covered by a test that would fail without it.",
    "Less suited to exploratory and UI work."],
 r:["Unit Test","Behaviour-Driven Development","Refactoring","Test Coverage"]},

{t:"Behaviour-Driven Development", a:"BDD", d:"Describing desired behaviour in structured natural language that both business and engineering can read.", l:"intermediate", g:["testing","practice"],
 b:["BDD expresses requirements in Given-When-Then scenarios, which serve simultaneously as specification, acceptance criteria and executable tests. Cucumber and SpecFlow run these directly against the system.",
    "Its real value is the conversation: writing scenarios together forces business and engineering to agree precisely on behaviour before code is written. Where that collaboration does not happen, BDD becomes a verbose way to write tests that only developers read."],
 k:["Given-When-Then scenarios readable by non-engineers.",
    "The value is the shared conversation, not the syntax.",
    "Without business participation it is just wordy test code.",
    "Scenarios double as living documentation of behaviour."],
 r:["Test-Driven Development","User Story","Unit Test","Documentation"]},

{t:"Mocking", d:"Replacing a real dependency with a controllable substitute during a test.", l:"core", g:["testing","practice"],
 b:["Test doubles come in kinds: a stub returns canned values, a mock asserts that it was called in a particular way, a fake is a working lightweight implementation, and a spy records calls while delegating to the real thing.",
    "Mock what you do not own and cannot control — payment gateways, email providers, the clock, random numbers. Mocking your own internal classes couples tests to implementation, so refactoring breaks them without any behaviour changing."],
 k:["Stub returns values; mock asserts interactions; fake is a working substitute.",
    "Mock external systems, the clock and randomness.",
    "Mocking your own internals makes tests break on refactor.",
    "Contract tests verify your mock matches the real service's behaviour."],
 r:["Unit Test","Test-Driven Development","Dependency Injection","Integration Test"]},

{t:"Test Coverage", d:"The proportion of code executed by the test suite.", l:"core", g:["testing","metrics"],
 b:["Coverage tools report which lines and branches ran during the tests. It is useful as a discovery tool — uncovered code is code nobody tested, which is worth knowing — and as a guard against coverage falling over time.",
    "It is a poor target. A test that executes a function without asserting anything meaningful counts as full coverage. Mandating 100% produces tests written to satisfy the metric rather than to catch bugs. Look at what is uncovered rather than at the number."],
 k:["Measures execution, not correctness — a test with no assertions still counts.",
    "Useful for finding untested code; poor as a target.",
    "Branch coverage is more informative than line coverage.",
    "Mutation testing measures whether tests actually detect changes."],
 r:["Unit Test","Test Pyramid","Static Analysis","Test-Driven Development"]},

{t:"Flaky Test", d:"A test that passes and fails intermittently without any change to the code.", l:"core", g:["testing","failure-mode"],
 b:["Flakiness comes from timing assumptions, shared state between tests, dependence on execution order, real network calls, time zones and unseeded randomness. Each failure costs somebody an investigation that finds nothing.",
    "The real damage is cultural: once a suite fails randomly, people rerun until it passes, and genuine failures get dismissed the same way. Quarantine flaky tests immediately and fix or delete them — a flaky test is worse than no test."],
 k:["Causes: timing, shared state, ordering, network, time zones, randomness.",
    "Trains the team to ignore failures — that is the real cost.",
    "Quarantine immediately, then fix or delete.",
    "Wait for conditions, never for fixed durations."],
 r:["End-to-End Test","Unit Test","CI/CD","Race Condition"]},

{t:"Refactoring", d:"Restructuring existing code without changing its external behaviour.", l:"core", g:["practice","quality"],
 b:["Refactoring improves clarity, removes duplication and makes future change easier, while behaviour stays identical. The safety net is the test suite: without tests you are not refactoring, you are rewriting and hoping.",
    "The discipline is to separate refactoring from behaviour change. Doing both in one commit makes review hard and makes it impossible to tell whether a bug came from the restructuring or the new feature."],
 k:["Behaviour must not change — that is what distinguishes it from rewriting.",
    "Tests are the safety net; without them it is not refactoring.",
    "Never mix refactoring and behaviour change in one commit.",
    "Refactor before adding a feature to make the change easy, then make it."],
 r:["Technical Debt","Unit Test","Code Smell","Test-Driven Development"]},

{t:"Technical Debt", d:"The future cost incurred by choosing an expedient solution now instead of a better one.", l:"core", g:["practice","concept"],
 b:["The metaphor is precise: you borrow time now and pay interest later in slower development. Deliberate debt — shipping a simpler design to hit a deadline, with a plan to revisit — can be a sound decision. Accidental debt from inexperience or neglect is just cost.",
    "The danger is that interest compounds invisibly. Each new feature takes longer, and the cause is diffuse enough that nobody can point at it. Making debt visible — a register, allocated capacity, or paying it down alongside related feature work — is what keeps it manageable."],
 k:["Deliberate and documented debt is a decision; accidental debt is a problem.",
    "Interest shows up as everything taking longer, with no obvious cause.",
    "Pay it down opportunistically, alongside work in the same area.",
    "A big-bang cleanup project rarely gets prioritised — small continuous payment does."],
 r:["Refactoring","Code Smell","Legacy System","Documentation"]},

{t:"Code Smell", d:"A surface indication that something in the code may be structurally wrong.", l:"intermediate", g:["practice","quality"],
 b:["Long methods, large classes, long parameter lists, duplicated code, feature envy, shotgun surgery (one change requiring edits in many places), primitive obsession. None is a bug, and each is a hint worth investigating.",
    "Smells are heuristics, not rules. A long method that is genuinely a linear sequence of steps may be clearer than five small ones scattered across a file. The judgement is whether the structure makes the code harder to understand and change."],
 k:["A hint that something may be wrong, not a defect in itself.",
    "Duplication, long methods, large classes and shotgun surgery are common ones.",
    "Context decides — smells are heuristics, not rules.",
    "The right response is usually a specific refactoring."],
 r:["Refactoring","Technical Debt","SOLID","DRY"]},

{t:"Linter", d:"A tool that analyses source code for style violations, likely errors and questionable patterns.", l:"core", g:["tooling","quality"],
 b:["Linters catch unused variables, unreachable code, shadowed names, missing await, accidental globals and hundreds of similar issues before they reach review. ESLint, Ruff, Clippy and golangci-lint are the common ones.",
    "Run them in CI so violations block merging, and pair with an auto-formatter so style is never discussed in review. The combination removes an entire category of low-value review comments."],
 k:["Catches likely errors and unsafe patterns before review.",
    "Run in CI and block on violations, or the rules are advisory.",
    "Pair with a formatter so style is never a review topic.",
    "Curate the rule set — a linter nobody can satisfy gets disabled."],
 r:["Static Analysis","Formatter","Code Review","CI/CD"]},

{t:"Formatter", d:"A tool that rewrites source code into a canonical style automatically.", l:"core", g:["tooling","quality"],
 b:["Prettier, Black, gofmt and rustfmt reformat code deterministically, so every file in the repository looks the same regardless of who wrote it. Running on save or as a pre-commit hook means formatting never appears in a diff or a review comment.",
    "The key insight of gofmt and Black is opinionation: by offering almost no configuration, they end style debates entirely. Nobody has to agree the style is best, only that it is consistent."],
 k:["Deterministic output — the same input always produces the same result.",
    "Removes style entirely from code review.",
    "Opinionated tools with few options end the debate fastest.",
    "Format on save or pre-commit, and enforce in CI."],
 r:["Linter","Code Review","CI/CD","Coding Standards"]},

{t:"Design Pattern", d:"A named, reusable solution to a recurring design problem.", l:"core", g:["practice","design"],
 b:["Patterns give a shared vocabulary — saying this is a strategy conveys structure and intent in three words. The Gang of Four catalogue divides them into creational (factory, builder, singleton), structural (adapter, decorator, facade) and behavioural (observer, strategy, command).",
    "The failure mode is applying patterns for their own sake, which produces elaborate structure for a problem that did not need it. Patterns are a vocabulary for describing solutions you arrived at, more than a menu to choose from in advance."],
 k:["Primarily a shared vocabulary for communicating design.",
    "Creational, structural and behavioural are the three families.",
    "Some patterns exist to work around missing language features.",
    "Applying patterns speculatively adds complexity without value."],
 r:["Singleton","Factory Pattern","Observer Pattern","Strategy Pattern","SOLID"]},

{t:"Singleton", d:"A pattern ensuring a class has exactly one instance, globally accessible.", l:"intermediate", g:["pattern","design"],
 b:["Singletons are used for connection pools, configuration and loggers — things where one instance genuinely makes sense. Implementations must handle thread safety, since two threads can otherwise create two instances simultaneously.",
    "It is the most criticised pattern for good reason: it is global mutable state with a class around it. It makes testing hard because the instance persists between tests, hides dependencies rather than declaring them, and creates coupling that is invisible at the call site. Dependency injection achieves the same lifetime control without any of that."],
 k:["Global mutable state with a respectable name.",
    "Persists between tests, causing order-dependent failures.",
    "Hides dependencies instead of declaring them.",
    "Dependency injection gives single-instance lifetime without the drawbacks."],
 r:["Design Pattern","Dependency Injection","Unit Test"]},

{t:"Factory Pattern", d:"Delegating object creation to a dedicated method or class rather than calling a constructor directly.", l:"intermediate", g:["pattern","design"],
 b:["A factory decides which concrete type to instantiate based on input or configuration, so calling code depends only on the interface. Adding a new type means changing the factory, not every call site.",
    "It is genuinely useful when creation is complex, when the concrete type depends on runtime information, or when you want to swap implementations for testing. Wrapping a simple `new` in a factory adds indirection for nothing."],
 k:["Callers depend on the interface, not the concrete class.",
    "Useful when the type depends on runtime input or configuration.",
    "Adding a type means changing one place, not every call site.",
    "Unnecessary when construction is trivial."],
 r:["Design Pattern","Interface","Dependency Injection","Polymorphism"]},

{t:"Observer Pattern", d:"Letting objects subscribe to another object's events and be notified when its state changes.", l:"core", g:["pattern","design"],
 b:["A subject maintains a list of observers and notifies them on change. The subject knows nothing about what its observers do, which decouples them completely. Event listeners, reactive state, pub/sub and the entire event-driven paradigm are this pattern.",
    "Two hazards recur: forgetting to unsubscribe causes memory leaks, because the subject holds a reference to an object that should have been collected; and notification cascades where one change triggers a chain of updates that are hard to trace."],
 k:["Subject notifies subscribers without knowing what they do.",
    "Always unsubscribe — forgotten listeners are a classic memory leak.",
    "Underlies DOM events, reactive state and pub/sub messaging.",
    "Cascading notifications are difficult to debug."],
 r:["Design Pattern","Publish-Subscribe","Event-Driven Architecture","Callback"]},

{t:"Strategy Pattern", d:"Encapsulating interchangeable algorithms behind a common interface, selectable at runtime.", l:"core", g:["pattern","design"],
 b:["Different pricing rules, sorting orders, compression algorithms or retry policies each become a class implementing the same interface, and the context holds whichever one it needs. Adding a new strategy requires no change to existing code.",
    "It is the standard alternative to a long conditional that switches on type. In languages with first-class functions, passing a function achieves the same thing with far less ceremony — which is what a comparator or a callback already is."],
 k:["Interchangeable algorithms behind one interface.",
    "Replaces long if/else or switch chains on type.",
    "In functional languages, a passed function is the same pattern.",
    "Open for extension, closed for modification — the O in SOLID."],
 r:["Design Pattern","Interface","Polymorphism","Higher-Order Function"]},

{t:"MVC", a:"Model-View-Controller", d:"An architectural pattern separating data, presentation and the logic that connects them.", l:"core", g:["pattern","architecture"],
 b:["The model holds data and business rules, the view renders it, and the controller handles input and coordinates the two. The separation means presentation can change without touching business logic, and the model can be tested without any UI.",
    "Variants abound — MVP, MVVM, MVU — differing in how state flows between the parts. Rails, Django, Spring MVC and ASP.NET MVC all popularised the server-side form. The recurring problem is fat controllers that accumulate business logic which belongs in the model or a service layer."],
 k:["Model holds data and rules; view renders; controller coordinates.",
    "Business logic belongs in the model, not the controller.",
    "MVVM and MVU are variants differing in state flow.",
    "Fat controllers are the characteristic failure mode."],
 r:["Design Pattern","Separation of Concerns","Component","Hexagonal Architecture"]},

{t:"SOLID", d:"Five object-oriented design principles aimed at code that is easier to change.", l:"core", g:["principle","design"],
 b:["Single responsibility: a class should have one reason to change. Open/closed: extend behaviour without modifying existing code. Liskov substitution: subtypes must be usable wherever their base type is. Interface segregation: many small interfaces beat one large one. Dependency inversion: depend on abstractions, not concrete implementations.",
    "They are heuristics for managing change, not laws. Applied dogmatically they produce a proliferation of tiny classes and interfaces that is harder to follow than the code they replaced."],
 k:["S: one reason to change. O: extend, do not modify.",
    "L: subtypes must honour the base type's contract.",
    "I: small focused interfaces. D: depend on abstractions.",
    "Heuristics for managing change, not rules to apply universally."],
 dg:"solid",
 r:["Design Pattern","Object-Oriented Programming","Dependency Injection","Interface"]},

{t:"DRY", a:"Don't Repeat Yourself", d:"Every piece of knowledge should have a single authoritative representation in a system.", l:"core", g:["principle","design"],
 b:["Duplicated knowledge means a change must be made in several places, and one will eventually be missed. DRY is about knowledge, not about identical-looking text — two functions that happen to look the same but encode different rules should stay separate.",
    "Over-applying it is a real failure mode: extracting a shared abstraction from two things that coincidentally resemble each other couples them, so a change to one distorts the other. The counter-advice — duplicate until the right abstraction is obvious — is sound."],
 k:["About duplicated knowledge, not duplicated characters.",
    "Coincidental similarity is not duplication.",
    "A premature wrong abstraction costs more than duplication.",
    "Rule of three: extract on the third occurrence, not the second."],
 r:["Code Smell","Refactoring","KISS","Abstraction"]},

{t:"KISS", a:"Keep It Simple", d:"Prefer the simplest solution that solves the problem.", l:"core", g:["principle","design"],
 b:["Complexity is the main long-term cost in software: it makes systems harder to understand, change, test and operate. Every abstraction, layer and configuration option is complexity that must be justified by present, not hypothetical, benefit.",
    "Simple is not the same as easy, and not the same as short. A simple design has few interacting parts and few special cases; clever one-liners are frequently the opposite of simple."],
 k:["Complexity is the dominant long-term cost.",
    "Simple means few interacting parts, not fewer characters.",
    "Justify each abstraction with a present need.",
    "Optimise for the reader — code is read far more than written."],
 r:["YAGNI","DRY","Technical Debt","Abstraction"]},

{t:"YAGNI", a:"You Aren't Gonna Need It", d:"Do not build functionality until it is actually required.", l:"core", g:["principle","design"],
 b:["Speculative generality — building for requirements you anticipate but do not have — usually turns out wrong. The predicted need does not arrive, or arrives in a shape the abstraction does not fit, and meanwhile everyone pays the complexity cost.",
    "It is not an argument against design or extensibility, but against implementing unrequested features. Keeping code simple and well-factored is what makes adding the real requirement easy when it appears."],
 k:["Speculative features usually predict the wrong requirement.",
    "You pay the complexity cost immediately and the benefit may never arrive.",
    "Not an argument against good design — an argument against extra features.",
    "Simple, well-factored code adapts more easily than pre-generalised code."],
 r:["KISS","DRY","Technical Debt","Refactoring"]},

{t:"Separation of Concerns", d:"Organising a system so each part addresses one distinct aspect.", l:"core", g:["principle","design"],
 b:["Business logic, persistence, presentation, validation and infrastructure are separate concerns, and mixing them produces code where changing the database means touching the UI. Separation lets each be understood, tested and changed independently.",
    "It underlies MVC, layered architecture, hexagonal architecture and the single responsibility principle. The judgement is where the boundaries go — too few and everything tangles, too many and simple changes require touching a dozen files."],
 k:["Each part addresses one aspect, changeable independently.",
    "Underlies MVC, layered and hexagonal architecture.",
    "Boundary placement is the actual design decision.",
    "Too many layers is as harmful as too few."],
 r:["SOLID","MVC","Hexagonal Architecture","Abstraction"]},

{t:"Documentation", d:"Written material explaining how a system works, how to use it and why it is built as it is.", l:"core", g:["practice","communication"],
 b:["Different documents serve different needs: tutorials for learning, how-to guides for specific tasks, reference for lookup, and explanation for understanding — the Diátaxis framework. Conflating them produces documents that serve none of the four well.",
    "The hardest problem is drift. Documentation near the code, generated from it, or tested (as runnable examples) stays accurate; documentation in a separate wiki decays quietly. Recording the reasoning behind decisions is the part that cannot be regenerated later."],
 k:["Tutorial, how-to, reference and explanation are four distinct forms.",
    "Documentation drifts unless it lives near or is generated from the code.",
    "Record why decisions were made — the reasoning cannot be recovered later.",
    "A README that gets someone running in five minutes is high-value."],
 r:["Architecture Decision Record","README","Changelog","Code Review"]},

{t:"Architecture Decision Record", a:"ADR", d:"A short document recording an architectural decision, its context and its consequences.", l:"intermediate", g:["practice","documentation"],
 b:["An ADR captures what was decided, what alternatives were considered, why this one was chosen, and what the consequences are. They are numbered, immutable, and superseded rather than edited — so the history of reasoning is preserved.",
    "Their value shows up two years later, when someone asks why the system uses this queue rather than that one. Without an ADR the answer is lost, and teams either preserve decisions no longer justified or repeat abandoned experiments."],
 k:["Context, decision, alternatives considered, consequences.",
    "Immutable and numbered — superseded, never rewritten.",
    "Answers why two years later, when everyone involved has left.",
    "Kept in the repository alongside the code they describe."],
 r:["Documentation","Technical Debt","Code Review"]},

{t:"README", d:"The entry-point document of a repository, explaining what the project is and how to start.", l:"core", g:["practice","documentation"],
 b:["A good README answers, quickly: what is this, why does it exist, how do I run it locally, how do I run the tests, and how do I contribute. Getting a new engineer from clone to running application in a few minutes is the single highest-value thing it can do.",
    "It is the most-read document in any repository and usually the least maintained. Keeping setup instructions accurate is worth more than any amount of architectural prose elsewhere."],
 k:["What, why, how to run, how to test, how to contribute.",
    "Optimise for time from clone to running locally.",
    "Test the setup instructions on a clean machine periodically.",
    "The most-read and least-maintained document in most repositories."],
 r:["Documentation","Architecture Decision Record","Changelog"]},

{t:"Agile", d:"A set of values favouring iterative delivery, working software and responsiveness to change.", l:"core", g:["process","practice"],
 b:["The Agile Manifesto values individuals and interactions over processes and tools, working software over documentation, customer collaboration over contract negotiation, and responding to change over following a plan. The intent was to replace long upfront specification with short feedback loops.",
    "In practice the word now often describes rigid ceremony — fixed rituals, story point accounting, status meetings called stand-ups — which is close to the opposite of the original intent. The underlying idea, short cycles with real feedback, remains sound."],
 k:["Four values, twelve principles — a mindset, not a methodology.",
    "Short feedback loops are the core mechanism.",
    "Frequently implemented as the ceremony it was meant to replace.",
    "Scrum, Kanban and XP are specific frameworks under the umbrella."],
 r:["Scrum","Kanban","Sprint","User Story","Waterfall"]},

{t:"Scrum", d:"An agile framework organising work into fixed-length iterations with defined roles and events.", l:"core", g:["process","practice"],
 b:["Scrum defines three roles (product owner, scrum master, developers), a sprint of one to four weeks, and events: sprint planning, daily stand-up, sprint review and retrospective. Work is drawn from a prioritised backlog into a sprint backlog.",
    "It works when the events serve their purpose — planning creates shared understanding, the stand-up surfaces blockers, the retrospective actually changes something. It fails when they become status reporting to a manager, which is the most common way it is implemented badly."],
 k:["Three roles, one sprint cadence, four events.",
    "The stand-up is for coordination, not status reporting upward.",
    "Retrospectives must produce changes or they are theatre.",
    "Velocity is a planning aid, never a productivity measure."],
 r:["Agile","Sprint","Kanban","User Story","Retrospective"]},

{t:"Kanban", d:"A method that visualises work on a board and limits how much is in progress at once.", l:"core", g:["process","practice"],
 b:["Work items move across columns representing stages. The essential mechanic is the work-in-progress limit: a column can hold only so many items, so starting something new requires finishing something first. That surfaces bottlenecks immediately.",
    "Unlike Scrum there are no fixed iterations — work is pulled continuously as capacity frees up. This suits support, operations and any stream of unpredictable work. Cycle time and throughput are the metrics that matter."],
 k:["Work-in-progress limits are the core mechanic, not the board.",
    "Continuous flow rather than fixed iterations.",
    "Bottlenecks become visible as items pile up before a column.",
    "Measure cycle time and throughput, not story points."],
 r:["Agile","Scrum","Sprint"]},

{t:"Sprint", d:"A fixed-length iteration, usually one to four weeks, ending with a potentially shippable increment.", l:"core", g:["process","practice"],
 b:["The team commits to a set of work at the start and aims to complete it by the end. The fixed timebox creates a regular cadence for planning, review and reflection, and a natural point at which priorities can change without disrupting work in progress.",
    "Sprints fail when the commitment becomes a deadline enforced from outside, or when scope is added mid-sprint. Both remove the predictability that was the entire point of the timebox."],
 k:["Fixed length, protected from mid-sprint scope changes.",
    "Ends with something demonstrable, not just work in progress.",
    "Commitment is the team's forecast, not an externally imposed deadline.",
    "Shorter sprints give faster feedback but more overhead per cycle."],
 r:["Scrum","Agile","User Story","Retrospective"]},

{t:"User Story", d:"A short description of a feature written from the user's point of view.", l:"core", g:["process","requirements"],
 b:["The template — as a [role], I want [capability], so that [benefit] — keeps the focus on who wants this and why, rather than on implementation. Acceptance criteria define what done means concretely.",
    "The card is meant to be a placeholder for a conversation, not a specification. Stories that describe implementation (as a user I want a Redis cache) have lost the point, and the missing why is what allows a team to propose a better solution than the one requested."],
 k:["As a [role], I want [capability], so that [benefit].",
    "A placeholder for a conversation, not a specification.",
    "Acceptance criteria define done concretely.",
    "INVEST: independent, negotiable, valuable, estimable, small, testable."],
 r:["Agile","Scrum","Sprint","Behaviour-Driven Development"]},

{t:"Retrospective", d:"A regular team meeting to reflect on how work is going and decide what to change.", l:"core", g:["process","practice"],
 b:["A retrospective asks what went well, what did not, and what to change. Its output should be a small number of concrete, owned actions — not a list of observations that recur unchanged every fortnight.",
    "Psychological safety determines whether it works. If raising a problem risks blame, people raise nothing that matters, and the meeting becomes a pleasant waste of time. One or two committed changes per retrospective beats ten aspirational ones."],
 k:["Output must be concrete, owned actions, not observations.",
    "One or two real changes beat a long list of intentions.",
    "Psychological safety determines whether real issues surface.",
    "The same problem recurring every time means nothing is being acted on."],
 r:["Scrum","Agile","Sprint","Postmortem"]},

{t:"Waterfall", d:"A sequential development model where each phase completes before the next begins.", l:"intermediate", g:["process","practice"],
 b:["Requirements, design, implementation, verification, maintenance — each fully finished before moving on. It assumes requirements are knowable upfront and stable, which holds for some engineering domains and rarely for software.",
    "Its failure mode is that problems surface at the end, when they are most expensive to fix, and by then the requirements have often changed anyway. It survives where regulation demands upfront specification and formal sign-off, and in some safety-critical and hardware-coupled contexts."],
 k:["Sequential phases with formal sign-off between each.",
    "Assumes requirements are knowable and stable upfront.",
    "Problems surface at the end, when they cost most to fix.",
    "Still used where regulation or hardware coupling demands it."],
 r:["Agile","Software Development Life Cycle","Scrum"]},

{t:"Software Development Life Cycle", a:"SDLC", d:"The overall process from initial idea through development, deployment and eventual retirement.", l:"intermediate", g:["process","practice"],
 b:["The phases are planning, requirements, design, implementation, testing, deployment and maintenance. Different methodologies traverse them differently: waterfall once in sequence, agile repeatedly in short cycles, DevOps continuously.",
    "Two points are consistently underweighted. Maintenance is the longest and most expensive phase by a wide margin, and decommissioning is a real phase — systems that are never retired accumulate as cost and security exposure indefinitely."],
 k:["Planning, requirements, design, build, test, deploy, maintain.",
    "Maintenance dominates total lifetime cost.",
    "Decommissioning is a real phase that is routinely skipped.",
    "Security must be present in every phase, not appended at the end."],
 r:["Agile","Waterfall","DevOps","Legacy System"]},

{t:"Pair Programming", d:"Two engineers working on the same code at the same workstation.", l:"intermediate", g:["practice","collaboration"],
 b:["One person writes while the other reviews and thinks ahead, swapping regularly. It produces continuous review, spreads knowledge fast, and is particularly effective for onboarding, unfamiliar code and genuinely difficult problems.",
    "It is tiring and not appropriate for everything — routine work is often faster done alone. Treat it as a tool for specific situations rather than a default mode, and rotate pairs so knowledge spreads across the team rather than pooling in one pair."],
 k:["Continuous review and fast knowledge transfer.",
    "Most valuable for onboarding, unfamiliar code and hard problems.",
    "Mentally demanding — not sustainable all day.",
    "Rotate pairs so knowledge spreads across the whole team."],
 r:["Code Review","Agile"]},

{t:"Debugging", d:"The process of finding and fixing the cause of incorrect behaviour.", l:"core", g:["practice","skill"],
 b:["Effective debugging is systematic rather than intuitive: reproduce reliably, narrow the search space by bisection, form a hypothesis, test it, and confirm the fix addresses the cause rather than the symptom. Reproducing reliably is usually the hardest and most valuable step.",
    "Print statements, debuggers, logs, `git bisect` and rubber duck explanation are all legitimate tools. The most common mistake is changing several things at once, which makes it impossible to know what actually fixed it."],
 k:["Reproduce first — an intermittent bug you cannot trigger is untrackable.",
    "Bisect the search space rather than reading everything.",
    "Change one thing at a time.",
    "Add a regression test before fixing, so it cannot silently return."],
 r:["Rubber Duck Debugging","Logging","Unit Test","Profiling"]},

{t:"Rubber Duck Debugging", d:"Explaining a problem aloud, in detail, to something that cannot help — and solving it in the process.", l:"core", g:["practice","technique"],
 b:["Articulating a problem forces you to make implicit assumptions explicit, and the wrong assumption usually becomes obvious mid-sentence. The listener genuinely need not understand anything; a colleague, a duck or a written message all work.",
    "This is why so many questions get answered by the person asking them halfway through typing. Writing the question out is the technique, whether or not you send it."],
 k:["Explaining forces implicit assumptions into the open.",
    "The listener does not need to understand or respond.",
    "Writing out a question often answers it before you send it.",
    "Works because the bug is usually in an assumption, not the code you are reading."],
 x:{lang:"text",code:"\"So this function takes a user id...\n and calls fetch_user, which returns a user...\n ...which returns a LIST of users.\n Oh.\"\n\nBug found. The duck said nothing."},
 r:["Debugging","Pair Programming","Code Review"]},

{t:"Profiling", d:"Measuring where a program actually spends its time and memory.", l:"core", g:["practice","performance"],
 b:["Profilers report which functions consume CPU, how much memory is allocated where, and where time is spent waiting. Sampling profilers interrupt periodically with low overhead; instrumenting profilers record every call with higher accuracy and higher cost.",
    "The rule is measure before optimising. Intuition about performance bottlenecks is wrong so often that it is safer to assume it is wrong. Flame graphs are the most effective visualisation, showing the call stack and time attribution together."],
 k:["Measure first — intuition about bottlenecks is usually wrong.",
    "Sampling profilers are cheap enough for production use.",
    "Flame graphs show call stacks and time attribution together.",
    "Profile under realistic load; toy workloads mislead."],
 r:["Benchmark","Debugging","Time Complexity","Performance Budget"]},

{t:"Benchmark", d:"A repeatable measurement of performance under controlled conditions.", l:"intermediate", g:["practice","performance"],
 b:["Reliable benchmarking requires warm-up (JIT compilation and caches need to settle), multiple runs to establish variance, and a workload that reflects real usage. Reporting a single number without variance is close to meaningless.",
    "Microbenchmarks are the most treacherous: compilers eliminate code whose results are unused, caches make repeated access unrealistically fast, and the result often has no relationship to production behaviour. Benchmark the realistic operation, not the isolated function."],
 k:["Warm up first, then measure many runs and report variance.",
    "Compilers optimise away work whose result is discarded.",
    "Microbenchmarks frequently measure something irrelevant.",
    "Benchmark realistic workloads, and profile to find what to benchmark."],
 r:["Profiling","Time Complexity","Performance Budget","Latency"]},

{t:"Legacy System", d:"An older system that remains in use and is difficult to change, but is too important to switch off.", l:"intermediate", g:["practice","maintenance"],
 b:["Legacy usually means valuable — it has been in production long enough to accumulate business rules that exist nowhere else, including in anyone's memory. The difficulty is not age but the absence of tests, documentation and people who understand it.",
    "The strangler fig pattern is the standard approach: route traffic through a facade, replace functionality piece by piece behind it, and retire the old system gradually. Big-bang rewrites fail at a notorious rate because they must reproduce behaviour nobody has documented."],
 k:["Legacy means valuable and hard to change, not merely old.",
    "The undocumented business rules are the real asset and the real risk.",
    "Strangler fig replaces incrementally behind a facade.",
    "Big-bang rewrites fail because the requirements are undocumented."],
 r:["Technical Debt","Refactoring","COBOL","Mainframe","Software Development Life Cycle"]},

{t:"Coding Standards", d:"Agreed conventions for how code in a project should be written.", l:"core", g:["practice","quality"],
 b:["Standards cover naming, structure, error handling, testing expectations and library choices. Their value is not that any particular convention is superior but that consistency reduces the effort of reading code someone else wrote.",
    "Automate everything automatable — formatters and linters should enforce mechanical rules so that human review addresses design and correctness. Written standards should cover only what tools cannot check."],
 k:["Consistency matters more than which convention was chosen.",
    "Automate everything a tool can enforce.",
    "Written standards should cover only what linters cannot.",
    "Document the reasoning for non-obvious rules or they get ignored."],
 r:["Linter","Formatter","Code Review","Documentation"]},

{t:"Formal Verification", d:"Mathematically proving that a program satisfies a specification.", l:"advanced", g:["practice","assurance"],
 b:["Rather than testing selected inputs, formal verification proves properties hold for all inputs. Model checkers such as TLA+ verify distributed algorithm designs; proof assistants such as Coq and Isabelle verify implementations; SPARK verifies Ada code for absence of runtime errors.",
    "It is expensive and requires specialist skill, so it is reserved for domains where failure is catastrophic — avionics, rail signalling, cryptographic implementations, consensus protocols. AWS uses TLA+ to verify the designs of core distributed services."],
 k:["Proves properties for all inputs, not just tested ones.",
    "TLA+ verifies designs; Coq and Isabelle verify implementations.",
    "Expensive and specialist — reserved for catastrophic-failure domains.",
    "Verifies against the specification; a wrong specification still proves wrong things."],
 r:["Ada","Static Analysis","Halting Problem","Distributed System"]}

]);
